export function mountNumbers(scope=document){mountTopic(scope,numbersMeta.slug,article=>{for(const [id,frames,body]of [['xor-lab',xorFrames,xorBody],['carry-lab',carryFrames,carryBody],['spiral-lab',spiralFrames,spiralBody]])mountTrace(article,id,frames,body);const lab=article.querySelector('[data-alignment-lab]'),input=lab.querySelector('input'),select=lab.querySelector('select');const draw=()=>{lab.querySelector('[data-align-x]').textContent=input.value;lab.querySelector('[data-alignment-body]').innerHTML=alignmentBody(Number(input.value),Number(select.value));};input.addEventListener('input',draw);select.addEventListener('change',draw);});}
